import{_ as a,o,c as e,ag as r}from"./chunks/framework.CAXxHpAX.js";const p=JSON.parse('{"title":"如何面对疾病与健康","description":"","frontmatter":{},"headers":[],"relativePath":"20-专题研究/topic-疾病与健康.md","filePath":"20-专题研究/topic-疾病与健康.md","lastUpdated":1778040484000}'),l={name:"20-专题研究/topic-疾病与健康.md"};function h(u,t,i,d,q,n){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="如何面对疾病与健康" tabindex="-1">如何面对疾病与健康 <a class="header-anchor" href="#如何面对疾病与健康" aria-label="Permalink to &quot;如何面对疾病与健康&quot;">​</a></h1><blockquote><p>专题分析：疾病中的修行智慧 组合模型：对境不住 + 性命双修 + 历境炼心</p></blockquote><hr><h2 id="一、了空居士对疾病的基本态度" tabindex="-1">一、了空居士对疾病的基本态度 <a class="header-anchor" href="#一、了空居士对疾病的基本态度" aria-label="Permalink to &quot;一、了空居士对疾病的基本态度&quot;">​</a></h2><p>了空居士对疾病的看法非常务实：<strong>身体有病就去看病，同时把疾病当作修行的机会</strong>。</p><blockquote><p><strong>&quot;病来了不要怕，看它是什么病，该吃药吃药，该打针打针。同时保持心灵的平静——有病不是世界末日。&quot;</strong></p></blockquote><p>— 答疑专辑</p><hr><h2 id="二、疾病中的三种修行态度" tabindex="-1">二、疾病中的三种修行态度 <a class="header-anchor" href="#二、疾病中的三种修行态度" aria-label="Permalink to &quot;二、疾病中的三种修行态度&quot;">​</a></h2><h3 id="_1-不恐惧" tabindex="-1">1. 不恐惧 <a class="header-anchor" href="#_1-不恐惧" aria-label="Permalink to &quot;1. 不恐惧&quot;">​</a></h3><blockquote><p><strong>&quot;过去心不可得，未来心不可得。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经18分-三心不可得">金刚经18分-三心不可得</a></p><p>对疾病的恐惧是一种对&quot;未发生的相&quot;的执着。该做的检查做了，就不要天天纠结&quot;是不是还有别的病&quot;。保持理智，科学就医。</p><h3 id="_2-不怨天尤人" tabindex="-1">2. 不怨天尤人 <a class="header-anchor" href="#_2-不怨天尤人" aria-label="Permalink to &quot;2. 不怨天尤人&quot;">​</a></h3><blockquote><p><strong>&quot;烦恼即菩提。疾病也是烦恼的一种，从中可以觉悟。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经5分-烦恼即菩提">金刚经5分-烦恼即菩提</a></p><p>病了可以问自己：&quot;这个病教了我什么？&quot;也许是提醒你休息，也许是让你学会接受不完美。</p><h3 id="_3-不硬撑" tabindex="-1">3. 不硬撑 <a class="header-anchor" href="#_3-不硬撑" aria-label="Permalink to &quot;3. 不硬撑&quot;">​</a></h3><blockquote><p><strong>&quot;身体不舒服就要适当休息。坐不了就躺着休息，想不清楚就让自己安静。&quot;</strong></p></blockquote><p>— 答疑专辑</p><p>修行是活的，不是死规矩。该休息休息，该吃药吃药，该调整姿势调整。</p><hr><h2 id="三、病中的修行方法" tabindex="-1">三、病中的修行方法 <a class="header-anchor" href="#三、病中的修行方法" aria-label="Permalink to &quot;三、病中的修行方法&quot;">​</a></h2><blockquote><p><strong>&quot;但安神息，不运火而火自运。心平气和了，身体自然健康。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></p><ul><li>能静坐就静坐，不能就躺着轻轻返观身体</li><li>做深呼吸放松全身</li><li>保持&quot;似守非守&quot;的观照</li></ul><blockquote><p><strong>&quot;身体虚无，精神状态好，二者俱佳——这就是形神俱妙。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></p><p>即使身体有病，只要心态对了，精神可以是饱满的。</p><hr><h2 id="四、业障与疾病" tabindex="-1">四、业障与疾病 <a class="header-anchor" href="#四、业障与疾病" aria-label="Permalink to &quot;四、业障与疾病&quot;">​</a></h2><blockquote><p><strong>&quot;以今世人轻贱故，先世罪业即为消灭。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;了即业障本来空，未了还需还宿债。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经16分-业障与清净心">金刚经16分-业障与清净心</a></p><p>受持《金刚经》的人被人轻贱，不生嗔恚，业障在清净心中自然消融。未悟的人，还是要老实面对因果、面对疾病。业障不是定业，是可以化解的。</p><hr><h2 id="五、常见误解" tabindex="-1">五、常见误解 <a class="header-anchor" href="#五、常见误解" aria-label="Permalink to &quot;五、常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th><th>原文依据</th></tr></thead><tbody><tr><td>修行人不会生病</td><td>身体是无常的，修行修的是心不被病痛绑住</td><td><a href="/60-原文段落/金刚经10分-缘起性空">金刚经10分-缘起性空</a></td></tr><tr><td>生病了还硬撑打坐</td><td>&quot;身体不舒服就要适当休息&quot;</td><td>答疑专辑</td></tr><tr><td>生病是业障，吃药没用</td><td>&quot;该吃药吃药，该打针打针&quot;——了空居士非常务实</td><td>答疑专辑</td></tr></tbody></table><hr><h2 id="六、推荐模型" tabindex="-1">六、推荐模型 <a class="header-anchor" href="#六、推荐模型" aria-label="Permalink to &quot;六、推荐模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-对境不住">对境不住</a> — 不被病痛和恐惧带跑</li><li><a href="/10-核心模型/model-性命双修">性命双修</a> — 身体是修行的基础</li><li><a href="/10-核心模型/model-历境炼心">历境炼心</a> — 病中是修行的好机会</li></ul><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-烦恼">dict-烦恼</a> — 疾病也是烦恼的一种，可以转为觉悟</li><li><a href="/50-概念资料/dict-形神俱妙">dict-形神俱妙</a> — 身体和精神都达到妙境</li></ul><hr><blockquote><p>创建日期：2026-05-06 | 修订：2026-05-07（全部原话添加出处链接，新增常见误解表，新增概念链接，新增业障与疾病节） 来源：五篇灵文、金刚经第10分/第16分/第18分、答疑专辑</p></blockquote>',45)])])}const s=a(l,[["render",h]]);export{p as __pageData,s as default};
